def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    last_me, last_opp = history[-1]
    if last_opp == 'C':
        return 'C'
    if n == 2 and history[0][1] == 'C' and history[1][1] == 'D':
        return 'C'
    if last_me == 'D':
        opp_def_streak = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                opp_def_streak += 1
            else:
                break
        if opp_def_streak >= 3:
            return 'D'
        opp_c = 0
        for i in range(n):
            if history[i][1] == 'C':
                opp_c += 1
        if opp_c >= n * 0.5:
            if rng.random() < 0.5:
                return 'C'
        return 'D'
    return 'D'
